        WHERE decode(key) = ?
        """,
        [str(parquet_path), OPENALEX_PAPER_TITLE_LOG_SHA256_METADATA_KEY],
    ).fetchone()
    if row is None or row[0] is None:
        return None
    return str(row[0])


